import * as M from './rules.mjs?v=patron-1';
import {characteristicNames,issueStep,steps,creationStepCount,experienceStep,reviewStep,restoreNavigation} from './ui.mjs?v=split-1';
import {gearSlots,gearOptions,equipment} from './equipment.mjs';
import {marketCatalog,purse,buyTrapping,formatMoney} from './market.mjs';
import {exportSheet,exportRecord} from './export.mjs';
import {folioData} from './folio.mjs';
const names=['species','careers','career-rolls','skills','talents','spells','gear','source'];
const data=await Promise.all(names.map(async n=>{const r=await fetch(`data/${n}.json`);if(!r.ok)throw Error(`Cannot load ${n}`);return r.json()}));
const R=Object.fromEntries(names.map((n,i)=>[n,data[i]]));
const STORAGE='wfrp-fifth-character-ledger-v1'+(new URLSearchParams(location.search).has('verify')?'-verification':'');let s=restoreNavigation(M.fresh());
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved?.version===1&&R.species[saved.species]&&R.careers.some(c=>c.id===saved.career))s={...s,...restoreNavigation(saved)};}catch{}
let folioOpen=new Set(),summaryExpanded=false,detailsState=new Map(),xpTab='Characteristics',careerFilter='All classes',skillSearch='',openedSkillGroups=new Set(),marketSearch='',openedMarketGroups=new Set();
try{const prefs=JSON.parse(localStorage.getItem(STORAGE+'-folio'));summaryExpanded=prefs?.expanded===true;folioOpen=new Set((Array.isArray(prefs?.open)?prefs.open:[]).filter(x=>['skills','talents','magic','gear'].includes(x)));}catch{}
function saveFolioPreferences(){try{localStorage.setItem(STORAGE+'-folio',JSON.stringify({expanded:summaryExpanded,open:[...folioOpen]}));}catch{}}
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(attrs,items,value,empty=false)=>`<select ${attrs}>${empty?'<option value="">Choose…</option>':''}${items.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`}).join('')}</select>`;
const button=(action,label,attrs='',style='quiet')=>`<button type="button" class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
const page=p=>`<span class="source">p. ${p}</span>`;
const locked=()=>s.ledger.length>0;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(s));}catch{toast('Draft could not be saved in this browser. Download a character file to keep it.')}}
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',6500);}
function freeSpellErrors(){let start=0,out=[];for(const g of M.spellGrants(R,s)){const chosen=s.spells.slice(start,start+g.count);if(chosen.length!==g.count||chosen.some(n=>!g.choices.some(x=>x.name===n)))out.push(`Choose ${g.count} free spells for ${g.talent}.`);start+=g.count;}if(s.spells.filter(Boolean).length>start)out.push('Remove spells without a matching Talent grant.');if(new Set(s.spells.filter(Boolean)).size!==s.spells.filter(Boolean).length)out.push('Choose different spells for each free choice.');return out;}
function errors(){const ids=new Set(marketCatalog(R).map(x=>x.id));return [...M.validation(R,s),...freeSpellErrors(),...gearSlots(R,s).filter(x=>/\d+d10/.test(x.name)&&!Object.keys(s.gearRolls).some(k=>k.startsWith(x.key+':'))).map(x=>`Roll the quantity for ${x.name}.`),...((s.purchases||[]).some(x=>!ids.has(x.id))?['An imported Trapping has no listed book price.']:[]),...(purse(R,s).remaining<0?['Trapping purchases exceed starting wealth.']:[])];}
function skillChoice(slot){const opts=M.options(R,slot.raw);return opts.length>1?select(`data-bind="skillChoices" data-key="${slot.key}" aria-label="${esc(slot.raw)}"`,opts,slot.name):`<strong>${esc(slot.name)}</strong>`;}
function talentDescription(name){const t=M.talentInfo(R,name);return `<details><summary>${esc(name)} ${page(t?.page||'—')}</summary><p>${esc(t?.text||'See the supplied Career and Talent descriptions.')}</p></details>`;}
function characteristicClass(k){const unlock=M.career(R,s).advanceScheme[k];return unlock?`career-characteristic career-level-${unlock} ${M.derive(R,s).level>=unlock?'career-current':'career-future'}`:'career-none';}
function characteristicTitle(k){const unlock=M.career(R,s).advanceScheme[k];return unlock?`Career level ${unlock} · ${M.derive(R,s).level>=unlock?'currently available':'currently non-career'}`:'Non-career Characteristic';}
function characteristicBadge(k,compact=true){const unlock=M.career(R,s).advanceScheme[k];if(!unlock)return compact?'':'<span class="characteristic-badge">Non-career</span>';const available=M.derive(R,s).level>=unlock;return `<span class="characteristic-badge" title="${esc(characteristicTitle(k))}">${compact?`L${unlock}${available?' · ✓':''}`:`Career L${unlock} · ${available?'✓ available':'later level'}`}</span>`;}
function characteristicLegend(){return `<div class="career-legend" aria-label="Career Characteristic colours">${[1,2,3,4].map(level=>`<span class="career-level-${level}"><i aria-hidden="true"></i>Level ${level}${level===1?' · starting':''}</span>`).join('')}</div><p class="small muted">✓ marks currently available Career Characteristics. Later levels become Career Characteristics when you reach that level; non-career purchases cost double. ${page(191)}</p>`;}
function spellDetailsBody(x){const fields=[['CN','cn'],['Range','range'],['Target','target'],['Duration','duration']].filter(([,key])=>x[key]!=null&&x[key]!==''),prefix=fields.map(([label,key])=>`${label}: ${x[key]}`).join(' ');const effect=x.text.startsWith(prefix)?x.text.slice(prefix.length).trim():x.text;return `<dl class="spell-meta">${fields.map(([label,key])=>`<div><dt>${label}</dt><dd>${esc(x[key])}</dd></div>`).join('')}</dl><p>${esc(effect)}</p>`;}
function spellDescription(x){return `<details class="spell-description"><summary>${esc(x.name)} · ${esc(x.category)} ${page(x.page)}</summary>${spellDetailsBody(x)}</details>`;}
function marketShop(){const wallet=purse(R,s),catalog=marketCatalog(R),byId=new Map(catalog.map(x=>[x.id,x])),groups=[...new Set(catalog.map(x=>x.category))];return `<section class="market section-gap"><h3>Buy extra Trappings ${page('296–316')}</h3><p class="small muted">During character creation, the book allows purchases without an Availability Test (p. 296). Prices below are the listed prices; items without a fixed price need your GM. Purchased gear does not earn a Career tracker box during creation (p. 36).</p><div class="market-balance"><div><span>Rolled</span><strong>${s.wealth?esc(`${s.wealth.amount} ${s.wealth.currency}`):'Not rolled'}</strong></div><div><span>Spent</span><strong>${formatMoney(wallet.spent)}</strong></div><div><span>Remaining</span><strong>${formatMoney(wallet.remaining)}</strong></div></div>${(s.purchases||[]).length?`<h3>Purchased items</h3><div class="market-purchases">${s.purchases.map((x,i)=>{const item=byId.get(x.id);return `<div class="market-purchase"><span><strong>${esc(item?.name||'Unknown item')}</strong><small>${item?`${esc(item.price)} · p. ${item.page}`:'Check imported character'}</small></span>${button('remove-trapping','Remove',`data-index="${i}" aria-label="Remove ${esc(item?.name||'item')}"`)}</div>`}).join('')}</div>`:''}<div class="field market-search"><label for="market-search">Search the book’s priced Trappings</label><input id="market-search" type="search" value="${esc(marketSearch)}" placeholder="Name, category, or page"></div><div class="market-catalog">${groups.map(category=>{const items=catalog.filter(x=>x.category===category);return `<details data-market-group data-category="${esc(category)}" ${openedMarketGroups.has(category)?'open':''}><summary>${esc(category)} <span class="minilabel">${items.length} items</span></summary>${items.map(x=>`<div class="market-item" data-market-search="${esc(`${x.name} ${x.category} ${x.page}`.toLowerCase())}"><div><strong>${esc(x.name)}</strong><small>${esc(x.availability)} · Enc ${x.enc===null?'—':x.enc} · ${page(x.page)}</small></div>${button('buy-trapping',`${esc(x.price)} · Buy`,`data-id="${esc(x.id)}" ${!s.wealth||x.pennies>wallet.remaining?'disabled':''}`,'primary')}</div>`).join('')}</details>`}).join('')}</div></section>`;}
function filterMarket(){const q=marketSearch.trim().toLowerCase();for(const group of document.querySelectorAll('[data-market-group]')){let visible=0;for(const row of group.querySelectorAll('[data-market-search]')){row.hidden=!!q&&!row.dataset.marketSearch.includes(q);if(!row.hidden)visible++;}group.hidden=visible===0;if(q&&visible)group.open=true;}}
function origins(){const sp=R.species[s.species];return `<span class="eyebrow">01 / Origins</span><h1>Origins & identity</h1><p class="muted">Choose your Species and give your character a name.</p><div class="cols"><div class="field"><label for="name">Character name</label><input id="name" data-bind="name" value="${esc(s.name)}" placeholder="Your character’s name" maxlength="90"></div><div class="field"><label for="species">Species</label>${select('id="species" data-bind="species"',Object.keys(R.species),s.species)}</div></div><div class="actions">${button('species-roll','Roll Species · d100','','primary')}<span class="small">${s.speciesMode==='first'?'+1 Fortune · first roll accepted':s.speciesAttempts?'Later roll / choice · no bonus':'Chosen Species · no random bonus'}</span></div><div class="notice">${s.species} begins with ${sp.fate} Fate, ${sp.fortune} Fortune and Movement ${sp.movement}. Fate and Fortune are separate values. ${page(sp.page)}<br>Accepting your first Species roll adds 1 Fortune. Accepting the first Species, Career and Characteristics rolls adds 1 Fate. ${page('23, 40')}</div><h3>Someone worth remembering</h3><div class="field"><label for="appearance">Appearance and background</label><textarea id="appearance" data-bind="appearance" placeholder="Age, height, eyes, hair, and a few words about your past…">${esc(s.appearance)}</textarea></div>${button('age','Roll age & height')}<div class="cols section-gap"><div class="field"><label for="ambition">Personal ambition</label><textarea id="ambition" data-bind="ambition" placeholder="What are you striving for?">${esc(s.ambition)}</textarea></div><div class="field"><label for="partyAmbition">Party ambition</label><textarea id="partyAmbition" data-bind="partyAmbition" placeholder="Agree this with your group (p. 42).">${esc(s.partyAmbition)}</textarea></div></div><p class="small muted">Biography is your character’s fiction. Rules and options come only from your supplied book.</p>`;}
function careerView(){const c=M.career(R,s),available=R.careers.filter(x=>x.species.includes(s.species)),visible=available.filter(x=>careerFilter==='All classes'||x.class===careerFilter),bonus=M.bonusTrappingLimit(R,s);return `<span class="eyebrow">02 / Career</span><h1>Choose your Career</h1><p class="muted">${available.length} of the book’s 64 Careers are available to ${s.species} characters.</p><div class="cols"><div class="field"><label for="class-filter">Class</label>${select('id="class-filter" data-bind="careerFilter"',['All classes',...[...new Set(available.map(x=>x.class))].sort()],careerFilter)}</div><div class="field"><label for="career">Career</label>${select('id="career" data-bind="career"',visible.map(x=>[x.id,x.name]),c.id)}</div></div><div class="actions">${button('career-roll',s.careerAttempts?'Roll another Career':'Roll Career · d100','','primary')}${s.careerAttempts===1?button('career-three','Roll two more'):''}</div>${s.careerOffers.length===3?`<p class="small">Choose one result for one bonus Trapping:</p><div class="actions">${s.careerOffers.map(id=>button('career-offer',esc(R.careers.find(c=>c.id===id).name),`data-id="${id}"`)).join('')}</div>`:''}<div class="notice">${bonus?`Select ${bonus} level-two Trapping${bonus===1?'':'s'}. Each earns one tracker box.${s.careerMode==='first'&&bonus<2?' This Career lists only one option.':''}`:'Chosen Career: standard starting Trappings, no bonus tracker boxes.'} ${page(36)}</div><h2>${esc(c.name)} <span class="source">${esc(c.class)} · p. ${c.page}</span></h2><p class="small">Begin as <strong>${esc(c.levels[0].name)}</strong> — ${c.levels[0].status} ${c.levels[0].standing}. Your first advances are ${Object.entries(c.advanceScheme).filter(([k,v])=>v===1).map(([k])=>k).join(', ')}.</p>${bonus?`<h3>Bonus Trappings <span class="counter">${s.bonusGear.length}/${bonus}</span></h3><div class="checklist">${M.bonusTrappingSlots(R,s).map(({name:t,i})=>`<label class="check-row"><input type="checkbox" data-bind="bonusGear" value="${i}" ${s.bonusGear.includes(i)?'checked':''}>${esc(t)}</label>`).join('')}</div>`:''}<h3>The Career path</h3>${c.levels.map(l=>`<details ${l.level===1?'open':''}><summary>${l.level}. ${esc(l.name)} · ${l.status} ${l.standing}</summary><p><strong>Skills:</strong> ${esc(l.skills.join(', '))}</p><p><strong>Talents:</strong> ${esc(l.talents.join(', '))}</p><p><strong>Trappings:</strong> ${esc(l.trappings.join(', '))}</p></details>`).join('')}`;}
function characteristics(){const c=M.career(R,s),sp=R.species[s.species],budget=s.charMode==='first'?6:s.charMode==='rearrange'?3:0;return `<span class="eyebrow">03 / Characteristics</span><h1>Characteristics</h1><p class="muted">Each score starts with your Species modifier and a roll or point allocation. ${page(38)}</p><div class="actions">${button('char-roll',s.charAttempts?'Reroll 10 × 2d10':'Roll 10 × 2d10','','primary')}${button('char-points','Allocate 100 points')}${s.charRolls.length?button('char-rearrange','Rearrange rolled values'):''}</div><div class="notice">${s.charMode==='points'?'Distribute exactly 100 points, from 4 to 16 in each Characteristic.':s.charMode==='first'?'First rolls retained in order: up to +6 starting points across your three Career Characteristics.':s.charMode==='rearrange'?'First results rearranged: up to +3 starting points across your three Career Characteristics.':'Rerolled results: assign each result once; no extra starting points.'}</div>${s.charMode==='points'?`<p><span class="counter">${s.points.reduce((a,b)=>a+b,0)} / 100 points allocated</span></p><div class="points-grid">${M.KEYS.map((k,i)=>`<div class="field characteristic-cell ${characteristicClass(k)}"><label for="point-${i}" title="${characteristicNames[k]}">${k}</label><div class="characteristic-meta">${characteristicBadge(k)}</div><input type="number" id="point-${i}" data-bind="points" data-key="${i}" min="4" max="16" value="${s.points[i]}"><small class="muted">+ ${sp.offsets[k]} Species</small></div>`).join('')}</div>`:`<table><thead><tr><th>Characteristic</th><th>2d10 result</th><th>Species</th><th>Initial</th></tr></thead><tbody>${M.KEYS.map((k,i)=>`<tr class="${characteristicClass(k)}"><td><span class="characteristic-label"><strong>${k}</strong>${characteristicBadge(k)}</span><small class="characteristic-name">${characteristicNames[k]}</small></td><td>${s.charMode==='first'?s.charRolls[i]:select(`data-bind="assignment" data-key="${i}" aria-label="Roll for ${k}"`,s.charRolls.map((v,j)=>[j,`${j+1}: ${v}`]),s.assignment[i])}</td><td>+${sp.offsets[k]}</td><td>${M.initial(R,s)[k]}</td></tr>`).join('')}</tbody></table>`}${characteristicLegend()}${budget?`<h3>Career starting increases <span class="counter">${Object.values(s.boost).reduce((a,b)=>a+b,0)} / ${budget}</span></h3><div class="cols">${M.KEYS.filter(k=>c.advanceScheme[k]===1).map(k=>`<div class="field"><label>${k} increase</label><input type="number" data-bind="boost" data-key="${k}" aria-label="${k} starting increase" min="0" max="${budget}" value="${s.boost[k]||0}"></div>`).join('')}</div>`:''}<p class="small muted">Starting increases and Talent bonuses are not purchased Advances. Each later Characteristic Advance adds +5; costs begin at 125 XP. ${page(191)}</p>`;}
function skills(){const slots=M.careerSkillSlots(R,s),total=Object.values(s.careerSkills).reduce((a,b)=>a+b,0);return `<span class="eyebrow">04 / Skills</span><h1>Starting Skills</h1><p class="muted">Every Advance is +5. Ordinary creation Skills may receive at most three Advances in total. ${page('38–39')}</p><h3>Species Skills <span class="counter">${s.speciesSkills.length} / 5 chosen</span></h3><p class="small muted">Choose five different Skills for one free Advance each. ${page(R.species[s.species].page)}</p>${M.speciesSkillSlots(R,s).map(slot=>`<div class="skill-row"><div>${skillChoice(slot)}</div><label class="check-row"><input type="checkbox" data-bind="speciesSkills" value="${slot.key}" aria-label="Choose Species ${esc(slot.name)}" ${s.speciesSkills.includes(slot.key)?'checked':''}> +5</label></div>`).join('')}<div class="notice">Fluent in ${R.species[s.species].languages.join(' and ')}: +30 in each native Language Skill. This explicit Species benefit is separate from the usual +15 limit.</div><h3>Career Skills <span class="counter">${total} / 8 Advances</span></h3>${slots.filter(x=>x.level===1).map(slot=>`<div class="skill-row"><div>${skillChoice(slot)}<div class="minilabel">${M.skillInfo(R,slot.name)?.char} · combined free advances +${(M.freeSkills(R,s)[slot.name]||0)*5}</div></div><div class="stepper">${button('skill-minus','−',`data-key="${slot.key}" aria-label="Decrease ${esc(slot.name)}"`)}<strong>${s.careerSkills[slot.key]||0}</strong>${button('skill-plus','+',`data-key="${slot.key}" aria-label="Increase ${esc(slot.name)}"`)}</div></div>`).join('')}<details class="section-gap"><summary>Specialisations for later Career levels</summary><p>Choose these now if you plan to advance your Career with XP.</p>${slots.filter(x=>x.level>1).map(slot=>`<div class="skill-row"><span class="minilabel">Level ${slot.level}</span>${skillChoice(slot)}</div>`).join('')}</details>`;}
function magicSection(){let idx=0;return M.spellGrants(R,s).map(g=>`<h3>${esc(g.talent)} — ${g.count} free ${M.GODS.includes(g.category)?'Miracle':'Spell'}${g.count===1?'':'s'}</h3>${Array.from({length:g.count},()=>{const i=idx++,chosen=g.choices.find(x=>x.name===s.spells[i]);return `<div class="field"><label for="spell-${i}">Free choice ${i+1}</label>${select(`id="spell-${i}" data-bind="spells" data-key="${i}"`,g.choices.map(x=>[x.name,`${x.name} · p. ${x.page}`]),s.spells[i],true)}</div>${chosen?spellDescription(chosen):''}`}).join('')}`).join('');}
function talents(){const sp=R.species[s.species],d=M.derive(R,s);return `<span class="eyebrow">05 / Talents</span><h1>Starting Talents</h1><p class="muted">Choose your special abilities and any starting spells or Miracles.</p><h3>Species Talents</h3>${sp.talents.map((opts,i)=>opts.length===1?`<span class="chip">${esc(opts[0])}</span>`:`<div class="field"><label for="talent-${i}">Species choice</label>${select(`id="talent-${i}" data-bind="talentChoices" data-key="species-${i}"`,opts,s.talentChoices[`species-${i}`]||opts[0])}</div>`).join('')}${sp.randomTalents?`<p class="small">${sp.randomTalents} random Talents from p. 23. Duplicates are rerolled and retained in your roll record.</p>${s.randomTalents.length?s.randomTalents.map((t,i)=>t==='Artistic'?`<div class="field"><label>Artistic specialisation</label>${select(`data-bind="talentChoices" data-key="random-${i}" aria-label="Artistic specialisation"`,M.options(R,'Artistic','talent'),s.talentChoices[`random-${i}`]||'Artistic (Drawing)')}</div>`:`<span class="chip">${esc(t)}</span>`).join(''):button('random-talents',`Roll ${sp.randomTalents} random Talents`,'','primary')}`:''}<div class="field section-gap"><label for="freeTalent">One free Career Talent</label>${select('id="freeTalent" data-bind="freeTalent"',M.careerTalentOptions(R,s),s.freeTalent,true)}</div>${s.freeTalent?talentDescription(s.freeTalent):''}${magicSection()}${M.knownSpells(R,s).some(x=>x.category==='Blessing')?`<div class="notice">Your patron grants six Blessings automatically (p. 220). All six appear in the export; overflow goes into the creation record.</div>`:''}<details class="section-gap"><summary>Read all your Talent rules</summary>${d.talents.map(talentDescription).join('')}</details>`;}
function gear(){const d=M.derive(R,s),eq=equipment(R,s);return `<span class="eyebrow">06 / Gear & money</span><h1>Gear & money</h1><p class="muted">Resolve your starting belongings, roll your purse, and buy extra equipment.</p><h3>Starting Trappings ${page(39)}</h3><p class="small muted">You receive your Class and first Career level’s gear. Spare items are retained. Resolve any choices below.</p>${gearSlots(R,s).filter(slot=>!slot.marketId).map(slot=>`<div class="ability"><div class="minilabel">${esc(slot.origin)}</div>${gearOptions(slot.name).length>1?select(`data-bind="gearChoices" data-key="${slot.key}" aria-label="${esc(slot.name)}"`,gearOptions(slot.name),s.gearChoices[slot.key]||gearOptions(slot.name)[0]):`<strong>${esc(slot.name.replace(/\{?(\d+)d10\}?/g,m=>s.gearRolls[`${slot.key}:${m}`]??m))}</strong>`}</div>`).join('')}${gearSlots(R,s).some(x=>/\d+d10/.test(x.name))?button('gear-quantities','Roll unresolved item quantities'):''}${eq.notes.map(n=>`<div class="notice">${esc(n)}</div>`).join('')}<h3>Starting wealth ${page(39)}</h3>${s.wealth?`<p><strong>${s.wealth.amount} ${s.wealth.currency}</strong></p>`:button('wealth','Roll starting wealth','','primary')}<p class="small muted">Based on ${M.career(R,s).levels[0].status} ${M.career(R,s).levels[0].standing}. A promotion does not grant another purse.</p>${d.talents.includes('Sturdy')||s.species==='Dwarf'?`<div class="field"><label for="sturdyRule">Book discrepancy: carrying capacity</label>${select('id="sturdyRule" data-bind="sturdyRule"',[['creation','Creation rule, p. 40: 2 × (SB + TB)'],['talent','Sturdy, p. 127: 2 × SB + TB']],s.sturdyRule)}<small class="muted">Both formulas appear in the book. Your selection is recorded.</small></div>`:''}`;}
function xpRow(type,name){
 const amount=['char','skill'].includes(type)&&s.advanceSize===1?1:5;
 const q=M.quote(R,s,type,name,amount),d=M.derive(R,s);
 const blocked=q.error||(errors().length?'Finish creation before spending XP.':'');
 const value=type==='char'?d.stats[name]:type==='skill'?d.stats[M.skillInfo(R,name)?.char]+Math.round((d.skills[name]||0)*5):0;
 const filter=type==='skill'?` data-skill-search="${esc(name.toLowerCase())}"`:'';
 const progress=(d.trackerProgress[`${type}:${name}`]||0)+1;
 const trackerLabel=blocked?'Not currently purchasable':q.tick?'Career · +1 tracker box':!q.inCareer?'Non-career · no tracker box':d.earnedBoxes>=36?'Career · tracker full':amount===1?`Career · ${progress%5}/5 toward a tracker box`:'Career · no tracker box';
 return `<div class="xp-row ${type==='char'?characteristicClass(name):''}"${filter}><div><strong>${esc(type==='char'?characteristicNames[name]:name)}</strong>${type==='char'?characteristicBadge(name,false):''}<p>${type==='talent'?'':`<span class="advance-result">${value} <span aria-hidden="true">→</span> ${value+amount} <small>+${amount}</small></span>`}<span class="tracker-effect">${trackerLabel}</span></p>${type==='talent'?talentDescription(name):''}</div><div>${button('buy',`${q.cost||'—'} XP`,`data-type="${type}" data-name="${esc(name)}" data-amount="${amount}" ${blocked?'disabled':''} title="${esc(blocked||'Purchase this improvement')}"`,'primary')}${blocked?`<p class="minilabel purchase-error">${esc(blocked)}</p>`:''}</div></div>`;
}
function experienceTalents(){
 const d=M.derive(R,s),available=[],known=[],unavailable=[];
 for(const name of M.careerTalentOptions(R,s,d.level)){
  const reason=M.invalidTalent(R,s,name);
  (reason.startsWith('Already known;')?known:reason?unavailable:available).push(name);
 }
 return `<section class="talent-group"><h3>Career Talents <span class="counter">${available.length}</span></h3><p class="small muted">Each purchase costs 100 XP. The button shows why a purchase is unavailable.</p>${available.length?available.map(n=>xpRow('talent',n)).join(''):'<p class="empty">No new Career Talents can be learned at this level.</p>'}</section>${known.length?`<details class="talent-catalog-group" data-group="known-talents"><summary>Already learned <span class="counter">${known.length}</span></summary><p class="small muted">These Talents cannot be purchased again under their normal rules.</p>${known.map(n=>`<div class="known-talent">${talentDescription(n)}</div>`).join('')}</details>`:''}${unavailable.length?`<details class="talent-catalog-group" data-group="unavailable-talents"><summary>Unavailable alternatives <span class="counter">${unavailable.length}</span></summary><p class="small muted">These choices have a rule restriction. Expand a Talent to read its rules.</p>${unavailable.map(n=>xpRow('talent',n)).join('')}</details>`:''}`;
}
function experienceSkills(){
 const d=M.derive(R,s);
 const all=[...new Set([...d.currentSkills,...Object.keys(d.skills),...R.skills.filter(x=>!x.advanced).flatMap(x=>x.grouped?x.options.map(o=>`${x.name} (${o})`):[x.name])])].sort((a,b)=>a.localeCompare(b));
 const career=all.filter(n=>d.currentSkills.includes(n));
 const trained=all.filter(n=>!d.currentSkills.includes(n)&&(d.skills[n]||0)>0);
 const other=all.filter(n=>!d.currentSkills.includes(n)&&!(d.skills[n]>0));
 const groups=Object.groupBy?Object.groupBy(other,M.base):other.reduce((out,n)=>((out[M.base(n)]??=[]).push(n),out),{});
 return `<div class="field skill-search"><label for="xp-skill-search">Find a Skill</label><input id="xp-skill-search" type="search" placeholder="Search Skills or specialisations…" value="${esc(skillSearch)}" autocomplete="off"><small class="muted">Your Career Skills come first. Browse other Basic Skills below.</small></div><p id="xp-skill-results" class="minilabel" aria-live="polite"></p><section class="skill-group"><h3>Current Career Skills <span class="counter">${career.length}</span></h3>${career.map(n=>xpRow('skill',n)).join('')}</section>${trained.length?`<section class="skill-group"><h3>Other trained Skills <span class="counter">${trained.length}</span></h3>${trained.map(n=>xpRow('skill',n)).join('')}</section>`:''}<section class="skill-group skill-catalog"><h3>Other Basic Skills <span class="counter">${other.length}</span></h3><p class="small muted">Skills with several specialisations can be expanded. Non-career Advances cost double.</p>${Object.entries(groups).map(([base,names])=>names.length===1?xpRow('skill',names[0]):`<details class="skill-catalog-group" data-group="${esc(base)}"><summary>${esc(base)} <span class="minilabel">${names.length} options</span></summary>${names.map(n=>xpRow('skill',n)).join('')}</details>`).join('')}</section>`;
}
function filterSkills(){
 const input=$('#xp-skill-search');if(!input)return;
 const query=skillSearch.trim().toLocaleLowerCase(),rows=[...document.querySelectorAll('[data-skill-search]')];let count=0;
 for(const row of rows){const match=!query||row.dataset.skillSearch.includes(query);row.hidden=!match;if(match)count++;}
 for(const group of document.querySelectorAll('.skill-catalog-group')){const match=!!group.querySelector('[data-skill-search]:not([hidden])');group.hidden=!!query&&!match;group.open=query?match:openedSkillGroups.has(group.dataset.group);}
 for(const group of document.querySelectorAll('.skill-group'))group.hidden=!!query&&!group.querySelector('[data-skill-search]:not([hidden])');
 const results=$('#xp-skill-results');if(results)results.textContent=query?`${count} matching Skill${count===1?'':'s'}`:'';
}
function experience(){
 const d=M.derive(R,s),e=errors(),c=M.career(R,s),q=M.quote(R,s,'promotion','');let rows='';
 if(xpTab==='Characteristics')rows=characteristicLegend()+M.KEYS.map(k=>xpRow('char',k)).join('');
 if(xpTab==='Skills')rows=experienceSkills();
 if(xpTab==='Talents')rows=experienceTalents();
 if(xpTab==='Magic')rows=spellShop();
 const last=s.ledger.at(-1),undo=last?button('undo',`Undo last: ${esc(last.name)}${['char','skill'].includes(last.type)?` +${last.amount===1?1:5}`:''}`,'','quiet'):'';
 return `<span class="eyebrow">07 / Experience</span><h1>Spend experience</h1><p class="muted">Each purchase has an exact price, source, and tracker effect. ${page('191, 364')}</p><div class="xp-balance"><div><span>XP budget</span><strong>${s.xp.toLocaleString()}</strong></div><div><span>Spent</span><strong>${d.spent.toLocaleString()}</strong></div><div class="remaining"><span>Available to spend</span><strong>${d.remaining.toLocaleString()}</strong></div></div><details class="budget-edit"><summary>Edit XP budget</summary><div class="budget-form"><div class="field"><label for="xp">Total XP budget</label><input id="xp" type="number" min="${d.spent}" step="1" value="${s.xp}"></div>${button('set-xp','Update budget','','secondary')}</div><p class="small muted">Includes spent XP. Unspent experience can be kept.</p></details>${undo?`<div class="undo-bar">${undo}<span class="minilabel">Recalculates XP and tracker boxes.</span></div>`:''}${e.length?issuePanel(e,'Finish creation to spend XP'):''}<div class="career-progress"><div class="split"><strong>${esc(c.levels[d.level-1].name)}</strong><span class="level-pill">Career level ${d.level}</span></div>${trackerBoxes(d)}${d.level<4?`<p>${button('promote','Advance Career · 100 XP',`${q.error||e.length?'disabled':''} title="${esc(q.error)}"`,'secondary')}</p><small>Requires the Advance Career Endeavour (p. 196). Using this button records that requirement as met.</small>`:''}</div><div class="page-tabs" role="tablist" aria-label="XP purchases">${['Characteristics','Skills','Talents','Magic'].map(t=>`<button role="tab" id="xp-tab-${t}" aria-controls="xp-content" tabindex="${t===xpTab?0:-1}" aria-selected="${t===xpTab}" class="quiet" data-action="xp-tab" data-tab="${t}">${t}</button>`).join('')}</div>${['Characteristics','Skills'].includes(xpTab)?`<div class="advance-choice"><span class="label">Advance by</span><div class="inline-choice" role="group" aria-label="Advance size">${[5,1].map(n=>button('advance-size',`+${n}`,`data-size="${n}" aria-pressed="${s.advanceSize===n}"`,s.advanceSize===n?'quiet active':'quiet')).join('')}</div><span class="small muted">${s.advanceSize===1?'Optional individual Advances: Appendix II, p. 364. Five +1 Advances in the same Career Skill or Characteristic earn one tracker box.':'+5 Advances: p. 191. An incomplete +1 band must reach five before returning to +5 on that Skill or Characteristic.'}</span></div>`:''}<div id="xp-content" role="tabpanel" aria-labelledby="xp-tab-${xpTab}" ${e.length?'class="unavailable"':''}>${rows}</div><details class="section-gap"><summary>Acquire a higher-level Career Trapping</summary><p>Only record an item from the next Career level, actually obtained with your GM. This does not create free gear or deduct coin. Each different next-level Trapping earns one box (pp. 43–44).</p><div class="field"><label for="new-trapping">Trapping</label>${select('id="new-trapping"',c.levels.filter(l=>l.level===d.level+1).flatMap(l=>l.trappings.map((t,i)=>[`${l.level}:${i}`,`Level ${l.level}: ${t}`])))}</div><div class="field"><label for="acquisition">How was it obtained?</label><input id="acquisition" placeholder="Gift, campaign reward, or purchase from other funds"></div>${button('acquire','Record acquisition',e.length?'disabled':'')}</details><details class="ledger-section" open><summary>XP ledger <span class="counter">${s.ledger.length} entries</span></summary>${ledgerTable()}</details><p class="small muted">Non-career Characteristics and Basic Skills cost double. Training and Unusual Learning Endeavours, Career changes, and GM awards are outside this creation workflow.</p>`;
}
function spellQuote(name,talent){const g=M.spellGrants(R,s).find(x=>x.talent===talent),known=M.knownSpells(R,s);if(!g)return null;const count=known.filter(x=>g.choices.some(y=>y.name===x.name)).length;const cost=g.category==='Witch!'?150+50*s.ledger.filter(x=>x.type==='spell'&&x.talent===talent).length:(g.category==='Petty'?50:100)*(Math.min(4,Math.floor(Math.max(0,count-1)/5))+1);return {type:'spell',name,talent,cost,tick:false,page:g.category==='Petty'?123:g.category==='Witch!'?128:M.GODS.includes(g.category)?121:115};}
function spellShop(){const grants=M.spellGrants(R,s),known=M.knownSpells(R,s);if(!grants.length)return '<p class="empty">Learn Petty Magic, Arcane Magic, Invoke, or Witch! to choose spells or Miracles.</p>';return `${magicSection()}${grants.map(g=>`<h3>${esc(g.talent)}</h3>${g.choices.filter(x=>!known.some(k=>k.name===x.name)).map(x=>{const q=spellQuote(x.name,g.talent);return `<div class="xp-row"><details><summary>${esc(x.name)} ${page(x.page)}</summary>${spellDetailsBody(x)}</details>${button('buy-spell',`${q.cost} XP`,`data-name="${esc(x.name)}" data-talent="${esc(g.talent)}" ${q.cost>M.derive(R,s).remaining?'disabled':''}`,'primary')}</div>`}).join('')}`).join('')}`;}
function ledgerTable(){const d=M.derive(R,s);return s.ledger.length?`<div class="table-wrap"><table><thead><tr><th># / Improvement</th><th>XP</th><th>Total</th><th>Source</th></tr></thead><tbody>${s.ledger.map((x,i)=>`<tr><td>${i+1}. ${esc(x.name)}${['char','skill'].includes(x.type)?` +${x.amount===1?1:5}`:''}<br><small>${d.trackerCredits[i]?'+1 tracker box':x.type==='promotion'?'Career advancement':x.amount===1&&(x.inCareer??x.tick)?`${d.trackerProgressAt[i]}/5 toward a tracker box`:'No tracker box'}</small></td><td>${x.cost}</td><td>${s.ledger.slice(0,i+1).reduce((a,b)=>a+b.cost,0)}</td><td>${page(x.page)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No XP spent yet. Unspent XP can be kept.</p>';}
function review(){const d=M.derive(R,s),c=M.career(R,s),eq=equipment(R,s),e=errors();return `<span class="eyebrow">08 / Review & export</span><h1>${esc(s.name||'Your character')}</h1><p class="muted">${s.species} · ${c.name} / ${c.levels[d.level-1].name} · ${d.status}</p>${e.length?issuePanel(e,'Finish these choices to export'):`<div class="notice success"><strong>Ready to export.</strong> Your sheet, free benefits, dice results and every XP purchase are accounted for.</div>`}<div class="actions">${button('sheet','Download character sheet',e.length?'disabled':'','primary')}${button('record','Download creation & XP record',e.length?'disabled':'','secondary')}</div><p class="small muted">The sheet uses your supplied fillable PDF. The complete creation record is appended to the sheet, including anything that exceeds its available rows. You can also download the record separately.</p>${[...d.warnings,...eq.notes].map(x=>`<div class="notice">${esc(x)}</div>`).join('')}<h3>Characteristics</h3><div class="table-wrap"><table><thead><tr><th></th>${M.KEYS.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${[['Initial*',k=>d.stats[k]-d.charAdv[k]],['XP advances',k=>'+'+d.charAdv[k]],['Current',k=>d.stats[k]]].map(([label,fn])=>`<tr><td>${label}</td>${M.KEYS.map(k=>`<td>${fn(k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="minilabel">*Includes Talent bonuses, which do not count as Advances.</p><details class="review-section" open><summary>Trained Skills</summary><table><thead><tr><th>Skill</th><th>Free</th><th>XP added</th><th>Current</th></tr></thead><tbody>${Object.entries(d.skills).filter(([n,v])=>v>0).sort().map(([n,v])=>`<tr><td>${esc(n)}</td><td>+${(M.freeSkills(R,s)[n]||0)*5}</td><td>+${Math.round((d.paidSkills[n]||0)*5)}</td><td>${d.stats[M.skillInfo(R,n)?.char]+Math.round(v*5)}</td></tr>`).join('')}</tbody></table></details><details class="review-section" ><summary>Talents</summary>${[...new Set(d.talents)].map(talentDescription).join('')}</details><details class="review-section" open><summary>Equipment</summary><p class="small">${eq.weapons.map(x=>`${esc(x.label)} (${x.group}, damage +${x.damage})`).join(' · ')}</p><p class="small">${eq.armour.map(x=>`${esc(x.label)} (${x.locations}, AP ${x.ap})`).join(' · ')}</p><p class="small">${eq.other.map(x=>esc(x.name)).join(' · ')}</p><p><strong>Encumbrance ${eq.unknown.length?`known subtotal ${eq.total}`:eq.total} / ${d.capacity}</strong></p>${!eq.unknown.length&&eq.total>d.capacity?'<div class="notice">Overburdened: Movement and Agility shown are intrinsic. Apply the load penalties from p. 299 during play.</div>':''}${eq.unknown.length?`<div class="notice">Check carried Encumbrance for: ${esc(eq.unknown.join('; '))}. Unlisted weights are left unknown. The sheet’s total stays blank until these are resolved.</div>`:''}</details><details class="review-section" ><summary>Wealth</summary><p>Remaining after purchases: <strong>${formatMoney(purse(R,s).remaining)}</strong> · spent ${formatMoney(purse(R,s).spent)}.</p><p>${s.wealth?`${s.wealth.amount} ${s.wealth.currency}`:'Not rolled'}</p></details>${M.knownSpells(R,s).length?`<h3>Spells, Blessings & Miracles</h3>${M.knownSpells(R,s).map(x=>`${spellDescription(x)}`).join('')}`:''}<details class="review-section" ><summary>Every XP accounted for</summary>${ledgerTable()}</details><details class="review-section" ><summary>Dice record</summary><p class="small muted">Each die uses the browser’s cryptographic random generator with rejection sampling. Raw faces, totals and timestamps are recorded. This is an editable local record, not a tamper-proof certificate.</p>${s.rolls.length?s.rolls.map(r=>`<div class="roll-entry"><strong>${esc(r.label)}</strong> · ${r.dice}: ${r.values.join(' + ')} = ${r.total} ${page(r.page)}<br><small class="muted">${esc(r.at)}</small></div>`).join(''):'<p class="empty">No dice have been rolled.</p>'}</details><div class="field section-gap"><label for="notes">Character notes / GM decisions</label><textarea id="notes" data-bind="notes">${esc(s.notes)}</textarea></div><details><summary>Source and interpretations</summary><p>Only ${esc(R.source.title)}, supplied as ${esc(R.source.sourceFile)}, is used. Printed and PDF pages match. MarkItDown extraction was checked against the PDF tables and Career symbols.</p><p>Navigation uses Initiative (p. 112); the sheet’s printed “Int” is corrected to I. Leather Breastplate uses Leather Jerkin statistics with your agreed naming note. The +45 Skill Advance costs 850 XP as printed (p. 191). Optional +1 prices follow Appendix II (p. 364). Five +1 Career Advances in the same Skill or Characteristic count as one tracker box, using your interpretation where the appendix is silent.</p><p>Unlisted weights are not invented. Situational Talent effects remain in their reference text. GM decisions still apply.</p></details>`;}
function issuePanel(issues,title){return `<div class="issue-panel"><strong>${esc(title)}</strong><ul>${issues.map(message=>`<li>${button('step',`${esc(message)} <span>Open ${esc(steps[issueStep(message)])}</span>`,`data-step="${issueStep(message)}"`)}</li>`).join('')}</ul></div>`;}
function trackerBoxes(d){const goal=[10,12,14,0][d.level-1];return goal?`<div class="tracker-boxes" role="img" aria-label="${d.ticks} of ${goal} Career tracker boxes">${Array.from({length:goal},(_,i)=>`<span class="${i<d.ticks?'filled':''}" aria-hidden="true">${i<d.ticks?'✓':''}</span>`).join('')}</div><p class="small muted">${d.ticks} / ${goal} boxes toward level ${d.level+1}</p>`:'<p class="small muted">Final Career level reached.</p>';}
function folioMenus(){
 const sections=folioData(R,s);
 return `<div class="folio-menus">${Object.entries(sections).map(([key,rows])=>`<details class="folio-section" data-folio-section="${key}" ${folioOpen.has(key)?'open':''}><summary><span class="folio-toggle" aria-hidden="true"></span><span>${key[0].toUpperCase()+key.slice(1)}</span><span class="folio-count">${rows.length}</span></summary>${rows.length?`<ul class="folio-list">${rows.map(row=>`<li><span>${esc(row.name)}</span>${key==='magic'?'':`<strong class="folio-value"${row.value===null?' title="Quantity not rolled yet"':''}>${row.value===null?'?':`${key==='skills'?'':'×'}${row.value}`}</strong>`}</li>`).join('')}</ul>`:'<p class="folio-empty">None yet.</p>'}</details>`).join('')}</div>`;
}
function render(){
 const folioScroll=document.querySelector('.sheet')?.scrollTop||0;
 const oldFocus=document.activeElement,focusId=oldFocus?.id,focusAction=oldFocus?.dataset?.action,focusName=oldFocus?.dataset?.name,focusTab=oldFocus?.dataset?.tab,focusKey=oldFocus?.dataset?.key,focusBind=oldFocus?.dataset?.bind,scrollPosition=window.scrollY;
 for(const detail of document.querySelectorAll('main details'))detailsState.set(detail.querySelector('summary')?.textContent.trim(),detail.open);
 if(document.querySelector('[data-market-group]'))openedMarketGroups=new Set([...document.querySelectorAll('[data-market-group][open]')].map(x=>x.dataset.category));
 if(!skillSearch&&document.querySelector('.skill-catalog'))openedSkillGroups=new Set([...document.querySelectorAll('.skill-catalog-group[open]')].map(x=>x.dataset.group));
 const d=M.derive(R,s),c=M.career(R,s),issues=errors(),pending=Array.from({length:steps.length},(_,i)=>issues.filter(x=>issueStep(x)===i));s.step=Math.max(0,Math.min(steps.length-1,s.step));
 const body=[origins,careerView,characteristics,skills,talents,gear,experience,review][s.step](),ready=creationStepCount-new Set(issues.map(issueStep)).size;
 $('#app').innerHTML=`<div class="workspace"><aside class="rail"><div class="rail-heading"><span class="eyebrow">Character creation</span><strong>Your next chapter</strong><p>${ready} of ${creationStepCount} creation steps ready</p><div class="creation-meter" role="img" aria-label="${ready} of ${creationStepCount} creation steps ready"><span style="width:${ready/creationStepCount*100}%"></span></div></div><div class="mobile-step field"><label for="mobile-step">Creation step</label>${select('id="mobile-step" data-bind="stepSwitch"',steps.map((name,i)=>[i,`${i+1}. ${name}`]),s.step)}</div><nav aria-label="Character creation steps"><ol class="steps">${steps.map((name,i)=>`<li><button class="${i===s.step?'active':''}" ${i===s.step?'aria-current="step"':''} data-action="step" data-step="${i}"><span class="step-number">${i<creationStepCount&&!pending[i].length?'✓':String(i+1).padStart(2,'0')}</span><span>${name}<small>${i<creationStepCount?(pending[i].length?`${pending[i].length} choice${pending[i].length===1?'':'s'} left`:'Ready'):i===experienceStep?'Optional advances':'Sheet & creation record'}</small></span></button></li>`).join('')}</ol></nav><div class="header-actions">${button('save-file','Save character')}${button('load-file','Load character')}${button('new','New character')}<input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="save-status">Saved automatically on this device</p><a href="data/source.json" class="source" target="_blank">Book source record</a></aside><main class="panel"><div class="stage-meta"><span>Step ${s.step+1} of ${steps.length}</span><span class="${pending[s.step].length?'pending-status':'ready-status'}">${s.step<creationStepCount?(pending[s.step].length?`${pending[s.step].length} choice${pending[s.step].length===1?'':'s'} remaining`:'✓ Ready'):issues.length?`${issues.length} creation choices remaining`:'✓ Creation complete'}</span></div>${locked()&&s.step<creationStepCount?`<div class="notice">Creation is locked while XP is spent. ${button('unlock','Clear advancement & edit creation')}</div><fieldset disabled class="creation-lock">${body}</fieldset>`:body}${s.step===5?marketShop():''}<div class="step-footer">${s.step?button('step','Back',`data-step="${s.step-1}"`):'<span></span>'}<span class="footer-position">${s.step+1} / ${steps.length}</span>${s.step<reviewStep?button('step',`Continue to ${steps[s.step+1]}`,`data-step="${s.step+1}"`,'primary'):button('step','Back to Experience',`data-step="${experienceStep}"`)}</div></main><aside class="sheet ${summaryExpanded?'expanded':''}" aria-label="Character summary"><div class="sheet-heading"><span class="eyebrow">Character folio</span><h2>${esc(s.name||'Your character')}</h2><p>${s.species} · ${esc(c.name)}</p><span class="profile-badge">${esc(c.levels[d.level-1].name)} · ${d.status}</span>${button('summary-toggle',summaryExpanded?'Hide details':'View character',`aria-expanded="${summaryExpanded}" aria-controls="sheet-body"`,'summary-toggle')}</div><div class="mobile-totals"><span><strong>${d.remaining.toLocaleString()}</strong> XP left</span><span><strong>${s.wealth?formatMoney(purse(R,s).remaining):'—'}</strong> coin</span></div><div id="sheet-body" class="sheet-body"><div class="stat-grid">${M.KEYS.map(k=>`<div class="${characteristicClass(k)}" title="${esc(characteristicNames[k]+': '+characteristicTitle(k))}"><small>${k}${c.advanceScheme[k]?` · L${c.advanceScheme[k]}`:''}</small><strong>${d.stats[k]}</strong></div>`).join('')}</div><div class="derived">${[['Wounds',d.wounds],['Movement',d.movement],['Fate',d.fate],['Fortune',d.fortune]].map(([k,v])=>`<div><span title="${k}">${k==='Movement'?'Move':k}</span><strong>${v}</strong></div>`).join('')}</div><div class="folio-balances"><div class="folio-xp"><span>XP remaining</span><strong>${d.remaining.toLocaleString()} <small>XP</small></strong><p>${d.spent.toLocaleString()} spent of ${s.xp.toLocaleString()}</p></div><div class="folio-coin"><span>Remaining coin</span><strong>${s.wealth?formatMoney(purse(R,s).remaining):'Not rolled'}</strong></div></div><div class="folio-line"><span>Current tracker</span><strong>${d.ticks} / ${[10,12,14,'—'][d.level-1]}</strong></div>${folioMenus()}<div class="folio-status ${issues.length?'pending':'complete'}"><span>${issues.length?`${issues.length} choices remaining`:'✓ Creation complete'}</span>${button('step',issues.length?'Finish choices':'Review & export',`data-step="${issues.length?issueStep(issues[0]):reviewStep}"`)}</div></div></aside></div><footer class="footer-note">Rules from your supplied Fifth Edition book · Your draft stays on this device</footer>`;
 for(const detail of document.querySelectorAll('main details')){const key=detail.querySelector('summary')?.textContent.trim();if(detailsState.has(key))detail.open=detailsState.get(key);}
 filterSkills();filterMarket();save();
 document.querySelector('.sheet').scrollTop=folioScroll;
 let focused=focusId?document.getElementById(focusId):null;
 if(!focused&&focusAction&&focusAction!=='step')focused=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===focusAction&&x.dataset.name===focusName&&x.dataset.tab===focusTab&&x.dataset.key===focusKey);
 if(!focused&&focusBind)focused=[...document.querySelectorAll('[data-bind]')].find(x=>x.dataset.bind===focusBind&&x.dataset.key===focusKey);
 focused?.focus({preventScroll:true});window.scrollTo({top:scrollPosition,behavior:'instant'});
}

function resetDependent(){s.skillChoices={};s.speciesSkills=[];s.careerSkills={};s.talentChoices={};s.randomTalents=[];s.freeTalent='';s.bonusGear=[];s.gearChoices={};s.gearRolls={};s.wealth=null;s.purchases=[];s.boost={};s.ledger=[];s.spells=[];}
function changeCareer(id,mode='choose'){s.career=id;s.careerMode=mode;s.skillChoices={};s.careerSkills={};s.freeTalent='';s.bonusGear=[];s.gearChoices={};s.gearRolls={};s.wealth=null;s.purchases=[];s.boost={};s.spells=[];careerFilter='All classes';}
function rolledCareer(){const n=M.roll(s,'Career',1,100,'36–37')[0],row=R['career-rolls'].find(r=>r[s.species]&&n>=r[s.species][0]&&n<=r[s.species][1]);s.careerAttempts++;return R.careers.find(c=>c.name.toLowerCase()===row.career.toLowerCase()).id;}
function download(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function action(el){const a=el.dataset.action;if(a==='step'){s.step=Number(el.dataset.step);render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(a==='new'){if(!confirm('Start a new character? Save the current character first if you want to keep it.'))return;s=restoreNavigation(M.fresh());}
 if(a==='save-file'){download(JSON.stringify(s,null,2),`${s.name||'character'}.json`,'application/json');toast('Character file saved.');return;}
 if(a==='load-file'){$('#import-file').click();return;}
 if(a==='unlock'){if(!confirm('Clear the XP ledger and spells so you can edit creation?'))return;s.ledger=[];s.spells=[];}
 if(a==='species-roll'){const n=M.roll(s,'Species',1,100,23)[0];s.speciesAttempts++;s.species=M.speciesResult(n);s.speciesMode=s.speciesAttempts===1?'first':'later';resetDependent();s.careerAttempts=0;s.careerMode='choose';s.careerOffers=[];if(!M.career(R,s).species.includes(s.species))s.career=R.careers.find(x=>x.species.includes(s.species)).id;toast(`d100 ${n} → ${s.species}`);}
 if(a==='age'){const sp=R.species[s.species],age=sp.age[0]+M.roll(s,'Age',sp.age[1],10,sp.page).reduce((a,b)=>a+b,0),height=sp.height[0]+M.roll(s,'Height (inches)',sp.height[1],10,sp.page).reduce((a,b)=>a+b,0);s.appearance=`${age} years; ${Math.floor(height/12)} ft ${height%12} in`+(s.appearance?`; ${s.appearance}`:'');}
 if(a==='career-roll'){const id=rolledCareer();s.careerOffers=[id];changeCareer(id,s.careerAttempts===1?'first':'later');}
 if(a==='career-three'){const first=s.careerOffers[0],second=rolledCareer(),third=rolledCareer();s.careerOffers=[first,second,third];changeCareer(first,'three');}
 if(a==='career-offer')changeCareer(el.dataset.id,'three');
 if(a==='char-roll'){s.charAttempts++;s.charRolls=M.KEYS.map(k=>M.roll(s,`${k} starting roll`,2,10,38).reduce((a,b)=>a+b,0));s.assignment=M.KEYS.map((_,i)=>i);s.charMode=s.charAttempts===1?'first':'reroll';s.boost={};}
 if(a==='char-points'){s.charMode='points';s.boost={};}
 if(a==='char-rearrange'){s.charMode=s.charAttempts===1?'rearrange':'reroll';s.boost={};}
 if(a==='skill-plus'||a==='skill-minus'){const key=el.dataset.key,now=s.careerSkills[key]||0,slot=M.careerSkillSlots(R,s,1).find(x=>x.key===key);if(a==='skill-plus'){if(Object.values(s.careerSkills).reduce((a,b)=>a+b,0)>=8)throw Error('All eight Career Advances are allocated.');if((M.freeSkills(R,s)[slot.name]||0)>=3)throw Error('This Skill already has three free Advances.');s.careerSkills[key]=now+1;}else s.careerSkills[key]=Math.max(0,now-1);}
 if(a==='random-talents'){if(s.randomTalents.length)return;const known=M.freeTalents(R,s);while(s.randomTalents.length<R.species[s.species].randomTalents){const n=M.roll(s,'Random Species Talent',1,100,23)[0],t=M.randomTalent(n);if(known.includes(t)||s.randomTalents.includes(t)){s.rolls.at(-1).label+=` — duplicate ${t}; rerolled`;continue;}s.randomTalents.push(t);}}
 if(a==='wealth'){if(s.wealth)return;const l=M.career(R,s).levels[0],count=l.status==='Brass'?2*l.standing:l.status==='Silver'?l.standing:0,total=count?M.roll(s,'Starting wealth',count,10,39).reduce((a,b)=>a+b,0):l.standing;s.wealth={amount:(l.status==='Brass'?20:l.status==='Silver'?10:2)+total,currency:l.status==='Brass'?'brass pennies':l.status==='Silver'?'silver shillings':'gold crowns'};}
 if(a==='buy-trapping'){const item=buyTrapping(R,s,el.dataset.id);toast(`${item.name} bought for ${item.price}.`);}
 if(a==='remove-trapping'){const index=Number(el.dataset.index);if(!Number.isInteger(index)||index<0||index>=(s.purchases||[]).length)throw Error('Purchased item not found.');s.purchases.splice(index,1);toast('Purchase removed and money restored.');}
 if(a==='gear-quantities'){for(const g of gearSlots(R,s))for(const m of g.name.matchAll(/\{?(\d+)d10\}?/g)){const key=`${g.key}:${m[0]}`;if(s.gearRolls[key]===undefined)s.gearRolls[key]=M.roll(s,`Trapping: ${g.name}`,Number(m[1]),10,39).reduce((a,b)=>a+b,0);}}
 if(a==='xp-tab')xpTab=el.dataset.tab;
 if(a==='summary-toggle'){summaryExpanded=!summaryExpanded;saveFolioPreferences();}
 if(a==='set-xp'){const n=Number($('#xp').value);if(!Number.isInteger(n)||n<M.derive(R,s).spent||n>1000000)throw Error('XP must be a whole number at least equal to the amount spent.');s.xp=n;toast('XP budget updated.');}
 if(a==='advance-size')s.advanceSize=Number(el.dataset.size);
 if(a==='buy'||a==='promote'){if(errors().length)throw Error('Finish the creation choices above first.');M.purchase(R,s,a==='promote'?'promotion':el.dataset.type,el.dataset.name||'',Number(el.dataset.amount)||5);toast(a==='promote'?'Career advanced.':'Improvement added to the XP ledger.');}
 if(a==='buy-spell'){if(errors().length)throw Error('Finish the free spell choices first.');const q=spellQuote(el.dataset.name,el.dataset.talent);if(!q||q.cost>M.derive(R,s).remaining)throw Error('Not enough XP.');if(M.knownSpells(R,s).some(x=>x.name===q.name))throw Error('Already known.');s.ledger.push(q);}
 if(a==='acquire'){if(errors().length)throw Error('Finish creation first.');const d=M.derive(R,s),[l,i]=$('#new-trapping').value.split(':').map(Number);if(l!==d.level+1||l>4)throw Error('Only the next Career level grants Trapping boxes.');const name=M.career(R,s).levels[l-1].trappings[i],reason=$('#acquisition').value.trim();if(!reason)throw Error('Record how the Trapping was obtained.');if(s.ledger.some(x=>x.type==='trapping'&&x.name===name)||s.bonusGear.some(i=>M.career(R,s).levels[1].trappings[i]===name))throw Error('This Trapping already earned a box.');s.ledger.push({type:'trapping',name,reason,level:l,cost:0,tick:d.earnedBoxes<36,page:'43–44'});}
 if(a==='undo'){s.ledger.pop();s.spells=s.spells.slice(0,M.spellGrants(R,s).reduce((a,g)=>a+g.count,0));}
 if(a==='sheet'||a==='record'){if(errors().length)throw Error('Finish creation before exporting.');el.disabled=true;toast('Preparing your PDF…');const bytes=a==='sheet'?await exportSheet(R,s):await exportRecord(R,s);download(bytes,`${s.name||'Character'}_${a==='sheet'?'Character_Sheet':'Creation_and_XP_Record'}.pdf`,'application/pdf');toast('Your PDF is ready.');}
 render();}
$('#app').addEventListener('toggle',e=>{const detail=e.target;if(!detail.isConnected||!detail.dataset.folioSection)return;const key=detail.dataset.folioSection;if(detail.open)folioOpen.add(key);else folioOpen.delete(key);saveFolioPreferences();},true);
$('#app').addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled||el.closest('fieldset[disabled]'))return;action(el).catch(err=>{toast(err.message);render();});});
$('#app').addEventListener('keydown',e=>{const tab=e.target.closest('[data-action="xp-tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['Characteristics','Skills','Talents','Magic'],index=tabs.indexOf(xpTab);xpTab=tabs[e.key==='Home'?0:e.key==='End'?3:(index+(e.key==='ArrowRight'?1:3))%4];render();document.getElementById('xp-tab-'+xpTab)?.focus({preventScroll:true});});
$('#app').addEventListener('input',e=>{if(e.target.id==='xp-skill-search'){if(!skillSearch)openedSkillGroups=new Set([...document.querySelectorAll('.skill-catalog-group[open]')].map(x=>x.dataset.group));skillSearch=e.target.value;filterSkills();return;}if(e.target.id==='market-search'){marketSearch=e.target.value;filterMarket();return;}const {bind}=e.target.dataset;if(['name','appearance','ambition','partyAmbition','notes'].includes(bind)){s[bind]=e.target.value;save();if(bind==='name'&&$('.sheet h2'))$('.sheet h2').textContent=s.name||'Your character';}});
$('#app').addEventListener('change',e=>{const el=e.target,{bind,key}=el.dataset;try{if(!bind||['name','appearance','ambition','partyAmbition','notes'].includes(bind))return;
 if(bind==='stepSwitch'){s.step=Number(el.value);render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(bind==='careerFilter'){careerFilter=el.value;render();return;}
 if(bind==='species'){s.species=el.value;s.speciesMode='choose';resetDependent();s.careerAttempts=0;s.careerMode='choose';s.careerOffers=[];if(!M.career(R,s).species.includes(s.species))s.career=R.careers.find(x=>x.species.includes(s.species)).id;}
 else if(bind==='career')changeCareer(el.value);
 else if(bind==='speciesSkills'||bind==='bonusGear'){const value=bind==='bonusGear'?Number(el.value):el.value;if(el.checked){const max=bind==='speciesSkills'?5:M.bonusTrappingLimit(R,s);if(s[bind].length>=max)throw Error(`Choose at most ${max}.`);s[bind].push(value);}else s[bind]=s[bind].filter(x=>x!==value);}
 else if(['points','boost','assignment'].includes(bind)){const n=Number(el.value);if(!Number.isInteger(n))throw Error('Use a whole number.');if(bind==='points'&&(n<4||n>16))throw Error('Allocate 4–16 points per Characteristic.');if(bind==='boost'&&(n<0||n>6))throw Error('Starting increases must be 0–6.');if(bind==='assignment'){const other=s.assignment.indexOf(n);s.assignment[other]=s.assignment[key];}s[bind][key]=n;}
 else if(['skillChoices','talentChoices','gearChoices'].includes(bind))s[bind][key]=el.value;
 else if(bind==='spells')s.spells[Number(key)]=el.value;
 else if(bind==='xp'){const n=Number(el.value);if(!Number.isInteger(n)||n<M.derive(R,s).spent||n>1000000)throw Error('XP must be a whole number at least equal to the amount spent.');s.xp=n;}
 else{s[bind]=el.value;if(bind==='freeTalent')s.spells=[];}
 render();}catch(err){toast(err.message);render();}});
$('#app').addEventListener('change',async e=>{if(e.target.id!=='import-file')return;try{const file=e.target.files[0];if(!file||file.size>3000000)throw Error('Choose a character JSON file under 3 MB.');const incoming=JSON.parse(await file.text());if(incoming.version!==1||!R.species[incoming.species]||!R.careers.some(c=>c.id===incoming.career)||!Array.isArray(incoming.ledger)||!Array.isArray(incoming.rolls))throw Error('Unsupported character file.');const old=s;s={...M.fresh(),...restoreNavigation(incoming)};try{M.derive(R,s);errors();}catch{s=old;throw Error('Character file contains invalid values.');}render();toast('Character loaded. Imported rolls are history, not newly generated dice.');}catch(err){toast(err.message);}});
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_character',annotations:{readOnlyHint:true,untrustedContentHint:true},description:'Read the current WFRP character, unresolved choices, XP ledger, and roll history.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({character:s,derived:M.derive(R,s),unresolved:errors()})}]})});document.modelContext.registerTool({name:'show_creation_step',annotations:{readOnlyHint:false,untrustedContentHint:false},description:'Open a creation step without changing character choices.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:1,maximum:steps.length}},required:['step']},execute:async({step})=>{if(!Number.isInteger(step)||step<1||step>steps.length)throw Error(`Step must be 1–${steps.length}.`);s.step=step-1;render();return {content:[{type:'text',text:`Opened ${steps[s.step]}`}]};}});}catch{}}
